import SwiftUI

/// An always-available "remote keyboard" docked under the focused terminal.
///
/// The terminal pane already renders cmux/Claude's own input line, so this bar
/// is deliberately styled as distinct keyboard chrome (not glass-terminal) to
/// read as *your* input bridge rather than a second prompt. It stays collapsed
/// to a slim field until tapped, then reveals command autocomplete and a
/// control-key row. It clears on send — the terminal's output remains the one
/// source of truth for what was typed.
struct TerminalInputBar: View {
    let surfaceTitle: String
    /// Reflects keyboard/compose focus up to the parent so it can give the
    /// focused terminal the whole screen while typing.
    @Binding var isActive: Bool
    var onSendText: (String) -> Void   // send text only (no newline)
    var onSendEnter: (String) -> Void  // send text + Enter (run it)
    var onSendKey: (String) -> Void    // send a control/navigation key

    @State private var draft = ""
    @FocusState private var focused: Bool
    @StateObject private var commandDict = CommandDictionary()
    // Landscape on iPhone reports a compact vertical size class. There the
    // keyboard eats most of the height, so the bar shrinks to a single chip
    // row + inline dismiss to leave room for the terminal.
    @Environment(\.verticalSizeClass) private var vSizeClass
    private var isCompact: Bool { vSizeClass == .compact }

    // A control chip either fires a named key via the bridge (`surface.send_key`,
    // matching SendTextView conventions) or injects literal text. cmux has no
    // key-name for the spacebar, so Space is sent as a literal " ".
    private enum KeyAction {
        case key(String)
        case text(String)
    }

    private struct ControlKey: Identifiable {
        let label: String
        let action: KeyAction
        // Lowercase aliases the compose field can filter on as you type.
        let terms: [String]
        // Space gets a wider chip so it reads as a spacebar.
        var isWide: Bool = false
        var id: String { label }
    }

    // Merged from the quick-actions "Input" section so the remote keyboard is a
    // superset of the popup — plus a spacebar the popup never had.
    private let controlKeys: [ControlKey] = [
        ControlKey(label: "esc", action: .key("Escape"), terms: ["esc", "escape"]),
        ControlKey(label: "⏎",   action: .key("enter"),  terms: ["enter", "return", "cr"]),
        ControlKey(label: "␣",   action: .text(" "),     terms: ["space", "spacebar", "spc"], isWide: true),
        ControlKey(label: "⇥",   action: .key("Tab"),    terms: ["tab"]),
        ControlKey(label: "⌃C",  action: .key("ctrl+c"), terms: ["ctrl+c", "ctrlc", "^c", "interrupt"]),
        ControlKey(label: "⌃D",  action: .key("ctrl+d"), terms: ["ctrl+d", "ctrld", "^d", "eof"]),
        ControlKey(label: "⌃Z",  action: .key("ctrl+z"), terms: ["ctrl+z", "ctrlz", "^z", "suspend"]),
        ControlKey(label: "⌃L",  action: .key("ctrl+l"), terms: ["ctrl+l", "ctrll", "^l", "clear"]),
        ControlKey(label: "↑",   action: .key("Up"),     terms: ["up", "arrow"]),
        ControlKey(label: "↓",   action: .key("Down"),   terms: ["down", "arrow"]),
        ControlKey(label: "←",   action: .key("Left"),   terms: ["left", "arrow"]),
        ControlKey(label: "→",   action: .key("Right"),  terms: ["right", "arrow"]),
    ]

    // The word being typed in the compose field doubles as a live filter for the
    // control chips (mirrors how command suggestions filter). If the word matches
    // no key it isn't a key query — a normal command — so we fall back to the full
    // row and keep navigation keys reachable while composing.
    private var filteredControlKeys: [ControlKey] {
        let q = currentWord.lowercased()
        guard !q.isEmpty else { return controlKeys }
        let matches = controlKeys.filter { ck in
            ck.label.lowercased().hasPrefix(q) || ck.terms.contains { $0.hasPrefix(q) }
        }
        return matches.isEmpty ? controlKeys : matches
    }

    var body: some View {
        VStack(spacing: isCompact ? 4 : 6) {
            if focused {
                if isCompact {
                    // One merged, scrollable row keeps the footprint minimal.
                    compactChipsRow
                } else {
                    header
                    suggestionsRow
                    controlKeyRow
                }
            }
            composeRow
        }
        .padding(.horizontal, 10)
        .padding(.vertical, isCompact ? 6 : 8)
        .background(
            RoundedRectangle(cornerRadius: 14)
                .fill(.ultraThinMaterial)
                .environment(\.colorScheme, .dark)
                .overlay(
                    RoundedRectangle(cornerRadius: 14)
                        .stroke(.white.opacity(0.12), lineWidth: 0.5)
                )
        )
        .padding(.horizontal, 8)
        .animation(.easeInOut(duration: 0.18), value: focused)
        .onChange(of: focused) { _, active in isActive = active }
        // If the bar is torn down while focused (quick actions open, the focused
        // surface closes or becomes a browser, tab switch), `.onChange(of:focused)`
        // won't fire — so reset here, or the parent leaves the workspace bar and
        // secondaries hidden forever.
        .onDisappear { isActive = false }
    }

    // MARK: - Header (only while composing)

    private var header: some View {
        HStack(spacing: 6) {
            Image(systemName: "terminal")
                .font(.system(size: 10))
                .foregroundStyle(.white.opacity(0.35))
            Text(surfaceTitle.isEmpty ? "terminal" : surfaceTitle)
                .font(.system(size: 11, weight: .medium, design: .monospaced))
                .foregroundStyle(.white.opacity(0.5))
                .lineLimit(1)
                .truncationMode(.middle)

            Spacer()

            // Dismiss lives top-right — where iOS keyboard "Done" belongs.
            Button {
                focused = false
            } label: {
                HStack(spacing: 4) {
                    Text("Done")
                    Image(systemName: "keyboard.chevron.compact.down")
                }
                .font(.system(size: 12, weight: .semibold))
                .foregroundStyle(.white.opacity(0.75))
            }
        }
    }

    // MARK: - Compose row

    private var composeRow: some View {
        HStack(spacing: 8) {
            Image(systemName: "keyboard")
                .font(.system(size: 14))
                .foregroundStyle(.white.opacity(0.4))

            TextField("", text: $draft, axis: .vertical)
                .focused($focused)
                .lineLimit(1...4)
                .font(.system(size: 14, design: .monospaced))
                .foregroundStyle(.white)
                .tint(.green)
                .autocorrectionDisabled()
                .textInputAutocapitalization(.never)
                .overlay(alignment: .leading) {
                    if draft.isEmpty {
                        Text("Send to \(surfaceTitle.isEmpty ? "terminal" : surfaceTitle)…")
                            .font(.system(size: 14, design: .monospaced))
                            .foregroundStyle(.white.opacity(0.3))
                            .allowsHitTesting(false)
                    }
                }

            if !draft.isEmpty {
                Button {
                    send(withEnter: false)
                } label: {
                    Image(systemName: "paperplane")
                        .font(.system(size: 15))
                        .foregroundStyle(.white.opacity(0.6))
                }
                Button {
                    send(withEnter: true)
                } label: {
                    Image(systemName: "return")
                        .font(.system(size: 15, weight: .semibold))
                        .foregroundStyle(.green)
                }
            }

            // Compact mode has no header, so the dismiss lives inline here.
            if isCompact && focused {
                Button {
                    focused = false
                } label: {
                    Image(systemName: "keyboard.chevron.compact.down")
                        .font(.system(size: 16, weight: .semibold))
                        .foregroundStyle(.white.opacity(0.7))
                }
                .padding(.leading, 2)
            }
        }
    }

    // MARK: - Command suggestions

    private var currentWord: String {
        let trimmed = draft.replacingOccurrences(of: "\n", with: " ")
        return trimmed.split(separator: " ").last.map(String.init) ?? ""
    }

    private var suggestionsRow: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(commandDict.suggestions(for: currentWord), id: \.self) { cmd in
                    suggestionChip(cmd)
                }
            }
            .padding(.horizontal, 2)
        }
        .frame(height: 30)
    }

    // MARK: - Control keys

    private var controlKeyRow: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 6) {
                ForEach(filteredControlKeys) { ck in
                    controlChip(ck)
                }
            }
            .padding(.horizontal, 2)
        }
        .frame(height: 32)
    }

    // MARK: - Compact chips (landscape)

    // Suggestions + control keys merged into a single scrollable row so the
    // whole bar is just this row + the compose row when the keyboard is up.
    private var compactChipsRow: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 6) {
                ForEach(commandDict.suggestions(for: currentWord), id: \.self) { cmd in
                    suggestionChip(cmd)
                }
                ForEach(filteredControlKeys) { ck in
                    controlChip(ck)
                }
            }
            .padding(.horizontal, 2)
        }
        .frame(height: 30)
    }

    private func suggestionChip(_ cmd: String) -> some View {
        Button {
            insertSuggestion(cmd)
        } label: {
            Text(cmd)
                .font(.system(size: 12, weight: .medium, design: .monospaced))
                .foregroundStyle(.white.opacity(0.85))
                .padding(.horizontal, 10)
                .padding(.vertical, 5)
                .background(Capsule().fill(.white.opacity(0.1)))
        }
    }

    private func controlChip(_ ck: ControlKey) -> some View {
        Button {
            fire(ck)
        } label: {
            Text(ck.label)
                .font(.system(size: 13, weight: .medium, design: .monospaced))
                .foregroundStyle(.white.opacity(0.75))
                .frame(minWidth: ck.isWide ? 72 : 34)
                .padding(.vertical, 6)
                .background(RoundedRectangle(cornerRadius: 7).fill(.white.opacity(0.08)))
        }
    }

    private func fire(_ ck: ControlKey) {
        switch ck.action {
        case .key(let key):   onSendKey(key)
        case .text(let text): onSendText(text)
        }
    }

    // MARK: - Actions

    private func send(withEnter: Bool) {
        let text = draft
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        learnCommand(text)
        if withEnter {
            onSendEnter(text)
        } else {
            onSendText(text)
        }
        draft = ""
        // Keep the keyboard up so the user can fire off several commands.
    }

    private func insertSuggestion(_ command: String) {
        let parts = draft.split(separator: " ", omittingEmptySubsequences: false).map(String.init)
        if parts.isEmpty {
            draft = command + " "
        } else {
            var updated = parts
            updated[updated.count - 1] = command
            draft = updated.joined(separator: " ") + " "
        }
    }

    private func learnCommand(_ input: String) {
        let firstWord = input.trimmingCharacters(in: .whitespacesAndNewlines)
            .split(separator: " ").first.map(String.init) ?? ""
        if !firstWord.isEmpty { commandDict.add(firstWord) }
    }
}

import SwiftUI
import UIKit

/// A UITextView-backed terminal renderer that supports text selection (copy)
/// and tappable links — neither of which SwiftUI's `Text` can do. It scrolls
/// itself and keeps pinned to the bottom for live output, but yields to the
/// user the moment they scroll up or start a selection.
///
/// Attributed-string construction and link detection run off the main thread
/// (see `TerminalTextRenderer`): a deep scrollback read is thousands of lines,
/// and building that inline in `updateUIView` — plus UIKit's synchronous
/// whole-document rescan that `dataDetectorTypes` performs on every
/// `attributedText` assignment — caused visible hitches whenever a poll landed
/// during an animation (keyboard, card resize).
struct TerminalTextView: UIViewRepresentable {
    let text: String
    let fontSize: CGFloat
    let textOpacity: Double
    /// When true, trailing markdown/punctuation is trimmed from detected links
    /// (e.g. `**url**` → `url`). Used by the transcript viewer, whose text is
    /// raw markdown. Live terminal cards keep links exactly as detected.
    var trimMarkdownLinks: Bool = false
    /// Fired (throttled) when the user deliberately over-scrolls past the top
    /// (a rubber-band pull) — the hook for opening the conversation-history viewer.
    var onScrolledToTop: (() -> Void)? = nil
    /// Reports whether the content is scrolled to its top, so callers can show a
    /// "pull for history" affordance only when it's actually reachable.
    var onTopStateChanged: ((Bool) -> Void)? = nil

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeUIView(context: Context) -> UITextView {
        let tv = UITextView()
        tv.isEditable = false
        tv.isSelectable = true
        tv.isScrollEnabled = true
        // Links come from our own detector pass in TerminalTextRenderer, not
        // dataDetectorTypes; tapping a .link attribute behaves the same either
        // way, but our pass runs off-main.
        tv.linkTextAttributes = [
            .foregroundColor: UIColor(red: 0.45, green: 0.72, blue: 1.0, alpha: 1.0),
            .underlineStyle: NSUnderlineStyle.single.rawValue,
        ]
        tv.backgroundColor = .clear
        tv.textContainerInset = UIEdgeInsets(top: 6, left: 8, bottom: 6, right: 8)
        tv.textContainer.lineFragmentPadding = 0
        tv.showsVerticalScrollIndicator = false
        tv.alwaysBounceVertical = true
        tv.delegate = context.coordinator
        // Terminal output is not natural language — don't fight the user with it.
        tv.autocorrectionType = .no
        tv.autocapitalizationType = .none
        context.coordinator.render(TerminalTextSnapshot(self), into: tv)
        return tv
    }

    func updateUIView(_ tv: UITextView, context: Context) {
        let coord = context.coordinator
        coord.onScrolledToTop = onScrolledToTop
        coord.onTopStateChanged = onTopStateChanged
        coord.render(TerminalTextSnapshot(self), into: tv)
    }

    final class Coordinator: NSObject, UITextViewDelegate {
        /// Whether new output should keep the view pinned to the bottom.
        /// True while the user is at (or near) the bottom; false once they
        /// scroll up to read scrollback.
        var autoScroll = true
        var onScrolledToTop: (() -> Void)?
        var onTopStateChanged: ((Bool) -> Void)?
        private var lastTopFire: TimeInterval = 0
        private var atTop = false

        /// What the text view currently shows. Compared against incoming
        /// snapshots, NOT tv.attributedText: the injected link attributes mean
        /// a freshly built string never equals what's on screen, and SwiftUI
        /// calls updateUIView far more often than the text changes.
        private var applied: TerminalTextSnapshot?
        /// The snapshot most recently handed to the background builder, so a
        /// re-render of the parent view doesn't queue a duplicate build.
        private var pending: TerminalTextSnapshot?
        private var generation = 0

        fileprivate func render(_ snapshot: TerminalTextSnapshot, into tv: UITextView) {
            if snapshot == pending || snapshot == applied { return }
            pending = snapshot
            generation += 1
            let gen = generation
            Task.detached(priority: .userInitiated) { [weak self, weak tv] in
                let attr = TerminalTextRenderer.build(snapshot)
                await MainActor.run {
                    // Only the newest build may land — an older one finishing
                    // late would put stale text (and a stale scroll) on screen.
                    guard let self, let tv, gen == self.generation else { return }
                    self.apply(attr, for: snapshot, to: tv)
                }
            }
        }

        fileprivate func apply(_ attr: NSAttributedString, for snapshot: TerminalTextSnapshot, to tv: UITextView) {
            // Don't clobber an in-progress selection (a live poll would
            // otherwise yank the text out from under the user mid-copy).
            // Resetting `pending` lets the next update retry once it clears.
            if tv.selectedRange.length > 0 {
                pending = applied
                return
            }

            // A history load prepends content above the viewport while the user
            // is reading scrollback. Detect it (old text is a strict suffix of
            // the new) so we can keep the same lines on screen instead of
            // letting them jump.
            let oldText = applied?.text ?? ""
            let isPrepend = !autoScroll && !oldText.isEmpty
                && snapshot.text.count > oldText.count && snapshot.text.hasSuffix(oldText)
            let oldHeight = tv.contentSize.height
            let oldOffset = tv.contentOffset

            tv.attributedText = attr
            applied = snapshot
            if autoScroll {
                scrollToBottom(tv)
            } else if isPrepend {
                // Layout synchronously so contentSize reflects the prepended
                // text, then shift the offset by exactly the added height — the
                // viewport stays anchored on the text the user was reading.
                tv.layoutIfNeeded()
                let delta = tv.contentSize.height - oldHeight
                if delta > 0 {
                    tv.setContentOffset(CGPoint(x: oldOffset.x, y: oldOffset.y + delta), animated: false)
                }
            }
        }

        private func scrollToBottom(_ tv: UITextView) {
            // Defer a runloop so layout reflects the new content size first.
            DispatchQueue.main.async {
                // Force pending layout so contentSize is correct for large
                // appends (e.g. a full-scrollback load), otherwise we under-scroll.
                tv.layoutIfNeeded()
                let bottom = max(0, tv.contentSize.height - tv.bounds.height + tv.adjustedContentInset.bottom)
                if bottom > 0 {
                    tv.setContentOffset(CGPoint(x: 0, y: bottom), animated: false)
                }
            }
        }

        func scrollViewDidScroll(_ scrollView: UIScrollView) {
            let threshold: CGFloat = 24
            let maxOffset = scrollView.contentSize.height - scrollView.bounds.height
            autoScroll = scrollView.contentOffset.y >= maxOffset - threshold

            // Report reaching the top so the history hint appears only then —
            // but only for USER-driven scrolls. A programmatic setContentOffset
            // (e.g. the prepend anchor) also lands here synchronously; mutating
            // SwiftUI @State from a view-update pass is a violation.
            if scrollView.isTracking || scrollView.isDragging || scrollView.isDecelerating {
                let nowAtTop = scrollView.contentOffset.y <= 4
                if nowAtTop != atTop {
                    atTop = nowAtTop
                    onTopStateChanged?(nowAtTop)
                }
            }

            // Trigger history on a deliberate over-scroll PAST the top — a
            // rubber-band pull (offset well negative), not just reaching the top.
            guard let onScrolledToTop,
                  scrollView.isTracking || scrollView.isDragging || scrollView.isDecelerating,
                  scrollView.contentOffset.y < -70
            else { return }
            let now = Date().timeIntervalSinceReferenceDate
            if now - lastTopFire > 1.5 {
                lastTopFire = now
                onScrolledToTop()
            }
        }
    }
}

/// The inputs that determine a rendered attributed string, captured as a value
/// so the background builder works from an immutable copy.
private struct TerminalTextSnapshot: Equatable {
    let text: String
    let fontSize: CGFloat
    let textOpacity: Double
    let trimMarkdownLinks: Bool

    init(_ view: TerminalTextView) {
        text = view.text
        fontSize = view.fontSize
        textOpacity = view.textOpacity
        trimMarkdownLinks = view.trimMarkdownLinks
    }
}

/// Builds TerminalTextView's attributed string. A standalone enum (not a member
/// of the View type) so its statics carry no MainActor isolation and can run in
/// a detached task.
private enum TerminalTextRenderer {
    static func build(_ snapshot: TerminalTextSnapshot) -> NSAttributedString {
        let style = NSMutableParagraphStyle()
        style.lineSpacing = 1
        let attr = NSMutableAttributedString(
            string: snapshot.text,
            attributes: [
                .font: UIFont.monospacedSystemFont(ofSize: snapshot.fontSize, weight: .regular),
                .foregroundColor: UIColor.white.withAlphaComponent(snapshot.textOpacity),
                .paragraphStyle: style,
            ]
        )
        addLinks(to: attr, trimTrailingJunk: snapshot.trimMarkdownLinks)
        return attr
    }

    private static let linkDetector: NSDataDetector? =
        try? NSDataDetector(types: NSTextCheckingResult.CheckingType.link.rawValue)

    /// Trailing characters that prose/markdown commonly places right after a URL
    /// but that aren't part of it. Data detectors grab them greedily — e.g.
    /// `**https://example.com/x**` yields `https://example.com/x**`, so the tap
    /// opens a broken URL. `)` is handled separately to preserve balanced parens.
    private static let trailingJunk = CharacterSet(charactersIn: "*_~`.,;:!?\"']}>")

    /// Detects URLs in the plain text and adds `.link` attributes. With
    /// `trimTrailingJunk` the trailing markdown/punctuation the detector
    /// over-captures is trimmed off first (transcript viewer); without it the
    /// detector's own match and URL are used verbatim (live terminal cards,
    /// matching what UITextView's built-in link detection produced).
    private static func addLinks(to attr: NSMutableAttributedString, trimTrailingJunk trim: Bool) {
        guard let detector = linkDetector else { return }
        let ns = attr.string as NSString
        let matches = detector.matches(in: attr.string, range: NSRange(location: 0, length: ns.length))
        for match in matches {
            var range = match.range
            var url = match.url
            if trim {
                while range.length > 0 {
                    let unit = ns.character(at: range.location + range.length - 1)
                    guard let scalar = Unicode.Scalar(unit) else { break }
                    if scalar == ")" {
                        // Keep a ) that closes a ( inside the URL (e.g.
                        // wiki/Foo_(bar)) — but trim unbalanced extras, as in
                        // "(see wiki/Foo_(bar))" where the last ) is prose.
                        let candidate = ns.substring(with: range)
                        let opens = candidate.lazy.filter { $0 == "(" }.count
                        let closes = candidate.lazy.filter { $0 == ")" }.count
                        if closes <= opens { break }
                    } else if !trailingJunk.contains(scalar) {
                        break
                    }
                    range.length -= 1
                }
                guard range.length > 0 else { continue }
                url = URL(string: ns.substring(with: range))
            }
            guard let url else { continue }
            attr.addAttribute(.link, value: url, range: range)
        }
    }
}

import SwiftUI

struct PaneCardView: View {
    let title: String
    let isFocused: Bool
    let hasNotification: Bool
    let isTranscribing: Bool
    let transcript: String
    var terminalText: String = ""
    var contentScale: CGFloat = 1.0
    var isBrowser: Bool = false
    var browserURL: String = ""
    /// When true, scrolling to the top of a focused card opens conversation
    /// history (claude agent surfaces).
    var canOpenHistory: Bool = false
    var onOpenHistory: (() -> Void)?
    @State private var notificationPulse = false
    @State private var terminalAtTop = false

    var body: some View {
        ZStack {
            // Glass background
            RoundedRectangle(cornerRadius: 12)
                .fill(.ultraThinMaterial.opacity(isFocused ? 0.4 : 0.2))
                .environment(\.colorScheme, .dark)

            // Notification pulse ring
            if hasNotification {
                RoundedRectangle(cornerRadius: 12)
                    .stroke(Color.orange, lineWidth: 2.5)
                    .opacity(notificationPulse ? 0.4 : 1.0)
                    .animation(
                        .easeInOut(duration: 1.2).repeatForever(autoreverses: true),
                        value: notificationPulse
                    )
                    .onAppear { notificationPulse = true }
                    .onDisappear { notificationPulse = false }
            }

            // Focus glow border
            RoundedRectangle(cornerRadius: 12)
                .stroke(borderColor, lineWidth: isFocused ? 1.5 : 0.5)

            // Content
            VStack(spacing: 0) {
                // Title bar
                titleBar

                // Body area
                ZStack(alignment: .topLeading) {
                    if isBrowser {
                        VStack(spacing: 8) {
                            Image(systemName: "globe")
                                .font(.system(size: isFocused ? 28 : 16))
                                .foregroundStyle(.white.opacity(0.2))
                            if !browserURL.isEmpty {
                                Text(browserURL
                                    .replacingOccurrences(of: "https://", with: "")
                                    .replacingOccurrences(of: "http://", with: ""))
                                    .font(.system(size: isFocused ? 10 : 7, design: .monospaced))
                                    .foregroundStyle(.white.opacity(0.4))
                                    .lineLimit(2)
                                    .multilineTextAlignment(.center)
                            }
                            if !title.isEmpty {
                                Text(title)
                                    .font(.system(size: isFocused ? 9 : 7, weight: .medium))
                                    .foregroundStyle(.white.opacity(0.3))
                                    .lineLimit(1)
                            }
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    } else if !terminalText.isEmpty {
                        terminalContentView
                    } else {
                        // Loading state for terminals before content arrives
                        VStack(spacing: 10) {
                            ProgressView()
                                .scaleEffect(0.7)
                                .tint(.white.opacity(0.3))
                            Text("Loading…")
                                .font(.system(size: 9, weight: .medium, design: .monospaced))
                                .foregroundStyle(.white.opacity(0.2))
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }

                    // Live speech transcript OVERLAYS the content while recording.
                    // It must not be a sibling branch of `terminalContentView`:
                    // that view is a UITextView (UIViewRepresentable), and
                    // swapping it out mid-recording leaves its UIKit layer on
                    // screen so the transcript never appears. Overlaying keeps the
                    // terminal mounted and paints the transcript on top.
                    if isTranscribing && !transcript.isEmpty {
                        Text(transcript)
                            .font(.system(size: 11, weight: .regular, design: .monospaced))
                            .foregroundColor(.green.opacity(0.9))
                            .lineLimit(4)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(.horizontal, 10)
                            .padding(.vertical, 8)
                            .background(.ultraThinMaterial.opacity(0.9))
                            .environment(\.colorScheme, .dark)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
            }
        }
        .shadow(color: isFocused ? .white.opacity(0.08) : .clear, radius: 12)
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .fill(isTranscribing ? Color.red.opacity(0.03) : .clear)
        )
    }

    // MARK: - Terminal content

    private var terminalContentView: some View {
        // UITextView-backed so output is selectable (copy) and URLs are tappable.
        // On a focused claude card, pulling to the top opens the conversation
        // history viewer (the terminal itself only shows claude's live viewport).
        TerminalTextView(
            text: terminalText,
            fontSize: (isFocused ? 9 : 7) * contentScale,
            textOpacity: isFocused ? 0.85 : 0.5,
            onScrolledToTop: (isFocused && canOpenHistory) ? { onOpenHistory?() } : nil,
            onTopStateChanged: (isFocused && canOpenHistory) ? { terminalAtTop = $0 } : nil
        )
        .overlay(alignment: .top) {
            // Only surface the affordance once the user is at the top; a further
            // pull-up past the top opens history.
            if isFocused && canOpenHistory && terminalAtTop {
                historyHint
                    .padding(.top, 4)
                    .transition(.opacity.combined(with: .move(edge: .top)))
            }
        }
        .animation(.easeInOut(duration: 0.18), value: terminalAtTop)
    }

    private var historyHint: some View {
        HStack(spacing: 5) {
            Image(systemName: "arrow.up")
                .font(.system(size: 8, weight: .semibold))
            Text("pull up for history")
                .font(.system(size: 8, weight: .medium, design: .monospaced))
        }
        .foregroundStyle(.white.opacity(0.5))
        .padding(.horizontal, 10)
        .padding(.vertical, 4)
        .background(Capsule().fill(.ultraThinMaterial).environment(\.colorScheme, .dark))
        .allowsHitTesting(false)
    }

    // MARK: - Title bar

    private var titleBar: some View {
        HStack(spacing: 6) {
            // Surface type icon
            Image(systemName: isBrowser ? "globe" : "terminal")
                .font(.system(size: 9, weight: .medium))
                .foregroundStyle(isFocused ? .white.opacity(0.5) : .white.opacity(0.2))

            // Title
            Text(title.isEmpty ? "untitled" : title)
                .font(.system(size: 10, weight: .medium, design: .monospaced))
                .foregroundStyle(isFocused ? .white.opacity(0.7) : .white.opacity(0.3))
                .lineLimit(1)
                .truncationMode(.middle)

            Spacer()

            // Recording indicator
            if isTranscribing {
                HStack(spacing: 4) {
                    Circle()
                        .fill(Color.red)
                        .frame(width: 6, height: 6)
                        .shadow(color: .red.opacity(0.6), radius: 3)
                    Text("REC")
                        .font(.system(size: 8, weight: .bold, design: .monospaced))
                        .foregroundStyle(.red.opacity(0.8))
                }
            }
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
        .background(
            Rectangle()
                .fill(isFocused ? Color.white.opacity(0.06) : Color.white.opacity(0.02))
        )
        // Top corners only
        .clipShape(
            UnevenRoundedRectangle(
                topLeadingRadius: 12,
                bottomLeadingRadius: 0,
                bottomTrailingRadius: 0,
                topTrailingRadius: 12
            )
        )
    }

    private var borderColor: Color {
        if hasNotification { return Color.orange.opacity(0.6) }
        if isFocused { return Color.white.opacity(0.5) }
        return Color.white.opacity(0.08)
    }
}

/// Identifies which surface's conversation history to present full-screen.
struct HistoryTarget: Identifiable, Equatable {
    let id: String
    let title: String
}

/// Full-screen viewer for a claude surface's conversation transcript. Loads on
/// appear, opens pinned to the latest exchange, scroll up for older history.
struct TranscriptSheetView: View {
    @EnvironmentObject var appState: AppState
    let target: HistoryTarget

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()
            VStack(spacing: 0) {
                header
                Divider().overlay(Color.white.opacity(0.1))
                body(for: appState.claudeTranscript[target.id] ?? "")
            }
        }
        .onAppear {
            // Always refetch on open so we show the latest session data, not a
            // stale cache from a previous viewing. Any cached text stays visible
            // (pinned to the bottom) until the fresh transcript replaces it.
            appState.loadClaudeTranscript(target.id)
        }
    }

    private var header: some View {
        HStack(spacing: 12) {
            VStack(alignment: .leading, spacing: 2) {
                Text("Conversation history")
                    .font(.system(size: 13, weight: .semibold))
                    .foregroundStyle(.white.opacity(0.9))
                Text(target.title)
                    .font(.system(size: 10, design: .monospaced))
                    .foregroundStyle(.white.opacity(0.4))
                    .lineLimit(1)
                // Diagnostic: the session the bridge resolved this surface to.
                // Lets a "wrong session" report name the exact session at a glance.
                if let session = appState.claudeTranscriptSession[target.id], !session.isEmpty {
                    Text("session \(session.prefix(8))")
                        .font(.system(size: 9, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.25))
                        .lineLimit(1)
                }
            }
            Spacer()
            Button { appState.loadClaudeTranscript(target.id) } label: {
                Image(systemName: "arrow.clockwise").font(.system(size: 15))
            }
            .tint(.white.opacity(0.6))
            .disabled(appState.claudeTranscriptLoading.contains(target.id))
            Button { appState.presentedHistory = nil } label: {
                Image(systemName: "xmark.circle.fill").font(.system(size: 22))
            }
            .tint(.white.opacity(0.5))
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 12)
    }

    @ViewBuilder
    private func body(for text: String) -> some View {
        if text.isEmpty {
            VStack(spacing: 10) {
                if appState.claudeTranscriptLoading.contains(target.id) {
                    ProgressView().tint(.white.opacity(0.4))
                    Text("Loading history…")
                        .font(.system(size: 11, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.3))
                } else if appState.claudeTranscriptMissing.contains(target.id) {
                    // Say so plainly rather than showing the newest session in
                    // the same folder, which is a different conversation.
                    Text("This surface's session file is missing")
                        .font(.system(size: 12, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.35))
                    Text("cmux points it at session \(appState.claudeTranscriptSession[target.id]?.prefix(8) ?? ""), which is no longer in ~/.claude/projects.")
                        .font(.system(size: 10, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.25))
                        .multilineTextAlignment(.center)
                        .padding(.horizontal, 40)
                } else {
                    Text("No conversation history")
                        .font(.system(size: 12, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.3))
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            TerminalTextView(text: text, fontSize: 12.5, textOpacity: 0.9, trimMarkdownLinks: true)
                .padding(.horizontal, 4)
        }
    }
}

