275	        .onDisappear {
276	            contentPollTimer?.invalidate()
277	            contentPollTimer = nil
278	        }
279	        .onChange(of: volumeButtonControls) { _, enabled in
280	            // Belt-and-braces. Today MainTabView switches on selectedTab, so
281	            // visiting Settings tears this view down and the toggle is picked
282	            // up by onAppear on the way back. This keeps the handler honest if
283	            // the tab ever starts retaining its view.
284	            if enabled {
285	                volumeHandler.start()
286	            } else {
287	                volumeHandler.stop()
288	            }
289	        }
290	        .onReceive(NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)) { _ in
291	            // Restart volume handler — iOS can deactivate AVAudioSession
292	            // when backgrounded, interrupted, or idle, killing the KVO observer
293	            if volumeButtonControls { volumeHandler.start() }
294	            appState.refreshSurfaces()
295	            // Content polling can be left dead after a background/tab switch
296	            // (the timer was invalidated but onAppear never re-fired). Restart
297	            // it here so terminal content resumes updating without a manual
298	            // navigation back into the view.
299	            startContentPolling()
300	        }
301	    }
